function backToSales(serial: string, exec: AdbExec, ops: ScreenOp[]) {
	for (let i = 0; i < 4; i++) {
		const xml = dumpXml(serial, exec);
		if (xml.includes("실매관리") && !xml.includes("그만두기")) return;
		const discard = parseNodes(xml).find((node) => node.text === "그만두기");
		if (discard) {
			const at = center(discard);
			act(
				serial,
				{ cmd: "tap", action: "그만두기를 누름", reason: "바꾼 가격이 저장되면 안 되어서" },
				() => {
					exec(["-s", serial, "shell", "input", "tap", String(at.x), String(at.y)]);
					sleep(400);
				},
				() => "수정을 저장하지 않고 닫음",
			);
			continue;
		}
		// 2026-11-11: 창을 닫으면 당근 홈으로 떨어진다. 홈에서 back 은 앞 앱으로 나가므로, 디플링크로 판매관리를 다시 연다.
		if (outsideSales(xml)) {
			openSales(serial, exec);
			return;
		}
		act(
			serial,
			{ cmd: "back", action: "뒤로 감", reason: "판매중 목록으로 돌아가려고" },
			() => {
				ops.push({ kind: "back" });
				exec(["-s", serial, "shell", "input", "keyevent", "KEYCODE_BACK"]);
				sleep(400);
			},
			() => (dumpXml(serial, exec).includes("판매관리") ? "판매관리로 돌아옴" : "아직 다른 화면"),
		);
	}
	openSales(serial, exec);
}

/** 홈 탭이나 다른 앱. 여기서 back 을 누르면 당근을 나간다. */
function outsideSales(xml: string): boolean {
	if (cooldownTip(xml) || onBumpSheet(xml) || xml.includes("게시글 수정") || xml.includes("수정 완료")) return false;
	const pkg = xml.match(/package="([^"]+)"/)?.[1] ?? "";
	if (pkg !== "" && pkg !== "com.towneers.www") return true;
	return xml.includes("나의 당근") && !xml.includes("판매관리");
}

