/**
 * 당근 끌어올리기 쿨타임.
 *
 * 공식 수치는 없다(FAQ 29는 하루 6개·글당 15회만 말한다). 여기 표는 횟수별 추정치다.
 * 폰에 남은 시간이 뜨면 그 관측값이 추정보다 우선한다.
 */

const MINUTE = 60_000;
const HOUR = 3_600_000;
const DAY = 86_400_000;

/** 글 하나를 끌어올릴 수 있는 최대 횟수. */
export const MAX_BUMPS = 15;

/** 하루에 끌어올릴 수 있는 글 수. */
export const DAILY_BUMP_LIMIT = 6;

/** `bumpCount`번째 끌올 뒤 기다리는 시간(ms). 아직 안 했으면 0. */
export function cooldownAfter(bumpCount: number): number {
	if (!Number.isFinite(bumpCount) || bumpCount < 1) return 0;
	if (bumpCount === 1) return 60 * HOUR;
	if (bumpCount === 2) return 72 * HOUR;
	return 96 * HOUR;
}

/** 끌올 시각 + 추정 쿨타임. 시각을 못 읽으면 null. */
export function nextBumpAt(bumpedAt: string, bumpCount: number): string | null {
	const at = Date.parse(bumpedAt);
	if (Number.isNaN(at)) return null;
	return new Date(at + cooldownAfter(bumpCount)).toISOString();
}

const REMAINING = /(\d+)\s*(일|시간|분)/g;

function unitMs(unit: string): number {
	if (unit === "일") return DAY;
	if (unit === "시간") return HOUR;
	return MINUTE;
}

/**
 * 폰에 뜬 `2일 12시간 뒤에 끌어올릴 수 있어요`·`30분 후`를 다음 끌올 가능 시각(ISO)으로 옮긴다.
 * 일·시간·분을 합쳐 읽고, 남은 시간이 없으면 null.
 */
export function parseCooldownText(text: string, now: number | Date = Date.now()): string | null {
	let total = 0;
	for (const match of text.matchAll(REMAINING)) {
		total += Number(match[1]) * unitMs(match[2]);
	}
	if (total <= 0) return null;
	const base = now instanceof Date ? now.getTime() : now;
	if (!Number.isFinite(base)) return null;
	return new Date(base + total).toISOString();
}

/** `N단위 전` → 분. 달·개월은 30일, 년은 365일로 어림한다. */
export function agoMinutes(n: number, unit: string): number {
	const day = 1_440;
	if (unit === "초") return 0;
	const per: Record<string, number> = {
		분: 1,
		시간: 60,
		일: day,
		주: 7 * day,
		달: 30 * day,
		개월: 30 * day,
		년: 365 * day,
	};
	return n * (per[unit] ?? day);
}

export function parseCaption(caption: string): {
	area: string;
	postedAgoDays: number | null;
	bumpAgoDays: number | null;
	bumpAgoMinutes: number | null;
	bumpCount: number | null;
} {
	const parts = caption
		.split("·")
		.map((part) => part.trim())
		.filter(Boolean);
	const area = parts[0] ?? "";
	let postedAgoDays: number | null = null;
	let bumpAgoDays: number | null = null;
	let bumpAgoMinutes: number | null = null;
	let bumpCount: number | null = null;
	for (const part of parts.slice(1)) {
		const bumpTimes = part.match(/^끌올\s+(\d+)회$/);
		if (bumpTimes) {
			bumpCount = Number(bumpTimes[1]);
			continue;
		}
		const bumpAgo = part.match(AGO_BUMP);
		if (bumpAgo) {
			bumpAgoMinutes = bumpAgo[1] ? agoMinutes(Number(bumpAgo[1]), bumpAgo[2]) : 0;
			bumpAgoDays = Math.floor(bumpAgoMinutes / 1_440);
			continue;
		}
		const posted = part.match(AGO);
		if (posted) postedAgoDays = posted[1] ? Math.floor(agoMinutes(Number(posted[1]), posted[2]) / 1_440) : 0;
	}
	// 끌올 문구가 없는 판매중 글은 아직 끌어올린 적이 없다.
	if (bumpCount === null && bumpAgoMinutes === null && postedAgoDays !== null) bumpCount = 0;
	return { area, postedAgoDays, bumpAgoDays, bumpAgoMinutes, bumpCount };
}

