function swipeAxis(serial: string, axis: { y1: number; y2: number; ms: number }) {
	const x = rand(340, 480);
	adb(serial, [
		"shell",
		"input",
		"swipe",
		String(x),
		String(axis.y1),
		String(x + rand(-20, 20)),
		String(axis.y2),
		String(axis.ms),
	]);
