function scrollUntilStable(serial: string, swipe: (serial: string) => void) {
	let prev = "";
	let stuck = 0;
	for (let i = 0; i < 40; i++) {
		swipe(serial);
		const parsed = parseSalesDump(settledXml(serial));
		if (!parsed.ok) continue;
		const key = visibleKey(parsed.cards);
		if (key && key === prev) {
			stuck += 1;
			if (stuck >= 2) return;
		} else {
			stuck = 0;
		}
		prev = key;
	}
}

function tapSellingTab(serial: string, xml: string) {
	const hit = xml.match(/content-desc="판매중 \d+"[^>]*bounds="\[(\d+),(\d+)\]\[(\d+),(\d+)\]"/);
	if (!hit) return;
	const x = Math.floor((Number(hit[1]) + Number(hit[3])) / 2);
	const y = Math.floor((Number(hit[2]) + Number(hit[4])) / 2);
	adb(serial, ["shell", "input", "tap", String(x), String(y)]);
}

function captureThumbs(serial: string, cards: DumpCard[]) {
	const needed = cards.filter((card) => card.photo);
	if (needed.length === 0) return;
	const dir = resolve(process.cwd(), "data", "thumbs");
	mkdirSync(dir, { recursive: true });
	const cap = resolve(dir, "_cap.png");
	if (!screenshot(serial, cap)) return;
	for (const card of needed) {
		const box = card.photo;
		if (!box) continue;
		const hash = createHash("sha1").update(card.title).digest("hex").slice(0, 16);
		const out = resolve(dir, `${hash}.jpg`);
		const cut = spawnSync("magick", [cap, "-crop", `${box.w}x${box.h}+${box.x}+${box.y}`, "+repage", out]);
		if (cut.status === 0) card.thumb = `/thumbs/${hash}.jpg`;
	}
}

