/**
 * 폰 문구 `끌올 N일·시간·분 전`을 지금 기준 ISO로. 문구가 없으면 이전 시각을 이어 쓴다.
 * 하루 단위만 있으면 그 날에 들어맞는 아는 시각을 유지하고, 안 맞으면 새 추정으로 갔는다(늦은 옛 추정도).
 */
function ingestedBumpedAt(card: DumpCard, prior: string | null, now: number): string | null {
	if (card.bumpAgoMinutes !== null && Number.isFinite(card.bumpAgoMinutes)) {
		return new Date(now - card.bumpAgoMinutes * 60_000).toISOString();
	}
	if (card.bumpAgoDays === null || !Number.isFinite(card.bumpAgoDays)) return prior;
	const estimate = new Date(now - card.bumpAgoDays * 1_440 * 60_000).toISOString();
	if (prior !== null && dayTextMatches(prior, card.bumpAgoDays, now)) return prior;
	return estimate;
}

/** `끌올 N일 전`은 경과 시간을 내려 일 단위다. N일 이상 (N+1)일 미만이면 같은 문구다. */
function dayTextMatches(prior: string, days: number, now: number): boolean {
	const at = Date.parse(prior);
	if (!Number.isFinite(at)) return false;
	const day = 1_440 * 60_000;
	const elapsed = now - at;
	return elapsed >= days * day && elapsed < (days + 1) * day;
}

/**
 * 다음 끌올 가능 시각. 폰이 보여 준 관측값이 있으면 그 값보다 늦은 추정으로만 덮는다.
 * 관측을 추정으로 앞당기지는 않는다. 옛 추정은 새 추정보다 늦아도 지키지 않는다.
 */
function ingestedNextBumpAt(input: {
	priorNext: string | null;
	priorBumpedAt: string | null;
	priorBumpCount: number | null;
	bumpedAt: string | null;
	bumpCount: number | null;
}): string | null {
	const count = input.bumpCount;
	const estimate =
		input.bumpedAt === null || count === null || count < 1 ? null : estimateNextBumpAt(input.bumpedAt, count);
	const observed = isObservedNext(input) ? input.priorNext : null;
	if (observed === null) return estimate ?? input.priorNext;
	return laterOf(observed, estimate);
}

/** 추정표와 같은 다음 시각은 추정이다. 그 외(폰 남은 시간·명시 관측)만 관측으로 지킨다. */
function isObservedNext(input: {
	priorNext: string | null;
	priorBumpedAt: string | null;
	priorBumpCount: number | null;
}): boolean {
	if (input.priorNext === null) return false;
	if (input.priorBumpedAt === null || input.priorBumpCount === null || input.priorBumpCount < 1) return true;
	return !sameInstant(input.priorNext, estimateNextBumpAt(input.priorBumpedAt, input.priorBumpCount));
}

function sameInstant(left: string | null, right: string | null): boolean {
	if (left === null || right === null) return false;
	const a = Date.parse(left);
	const b = Date.parse(right);
	return Number.isFinite(a) && a === b;
}

